import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { User } from 'firebase/auth';
import { authService, RegisterParams } from '../services/authService';
import { UserProfile, AuthState } from '../types/auth';
import { notificationService } from '../services/notificationService';

interface AuthContextType extends AuthState {
  signIn: (email: string, pass: string) => Promise<UserProfile>;
  register: (params: RegisterParams) => Promise<void>;
  signOut: () => Promise<void>;
  reloadUser: () => Promise<UserProfile | null>;
  updateDeclaredRounds: (newRounds: number) => Promise<void>;
  requestDeclaredRoundsChange: (newRounds: number) => Promise<void>;
  cancelDeclaredRoundsRequest: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [firebaseUser, setFirebaseUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    const unsubscribe = authService.subscribeToAuthState((profile, fbUser) => {
      setUser(profile);
      setFirebaseUser(fbUser);
      setIsLoading(false);
      if (profile) {
        if (profile.role === 'counsellor') {
          notificationService.checkAndDispatchAdminAlerts(profile).catch(() => {});
        } else {
          notificationService.scheduleDailyReminders(profile).catch(() => {});
        }
      }
    });

    return () => unsubscribe();
  }, []);

  const signIn = async (email: string, pass: string): Promise<UserProfile> => {
    // Note: Do NOT toggle global isLoading here. LoginScreen manages its own localized
    // isSubmitting state. Setting global isLoading causes RootNavigator to unmount LoginScreen,
    // which resets user-typed form inputs (email/username) on invalid password errors.
    const profile = await authService.signIn(email, pass);
    setUser(profile);
    return profile;
  };

  const register = async (params: RegisterParams) => {
    setIsLoading(true);
    try {
      const profile = await authService.registerCounselee(params);
      setUser(profile);
    } finally {
      setIsLoading(false);
    }
  };

  const signOut = async () => {
    setIsLoading(true);
    try {
      await authService.signOut();
      setUser(null);
      setFirebaseUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  const reloadUser = async (): Promise<UserProfile | null> => {
    const targetUid = user?.uid || firebaseUser?.uid;
    const email = user?.email || firebaseUser?.email;
    if (targetUid || email) {
      const refreshed = await authService.getUserProfile(targetUid || '', true, email || undefined);
      if (refreshed) {
        setUser(refreshed);
        return refreshed;
      }
    }
    return null;
  };

  const updateDeclaredRounds = async (newRounds: number) => {
    if (!user?.uid) return;
    try {
      await authService.updatePermittedProfile(user.uid, { declaredRounds: newRounds });
    } catch (e) {
      console.warn('Error updating declared rounds:', e);
    }
    setUser((prev) => (prev ? { ...prev, declaredRounds: newRounds } : prev));
  };

  const requestDeclaredRoundsChange = async (newRounds: number) => {
    if (!user?.uid) return;
    try {
      await authService.requestTargetRoundsChange(user.uid, newRounds);
    } catch (e) {
      console.warn('Error requesting declared rounds change:', e);
    }
    setUser((prev) => (prev ? { ...prev, targetRoundsRequested: newRounds, targetRoundsRequestedAt: new Date().toISOString() } : prev));
  };

  const cancelDeclaredRoundsRequest = async () => {
    if (!user?.uid) return;
    try {
      await authService.cancelTargetRoundsRequest(user.uid);
    } catch (e) {
      console.warn('Error cancelling declared rounds request:', e);
    }
    setUser((prev) => (prev ? { ...prev, targetRoundsRequested: undefined, targetRoundsRequestedAt: undefined } : prev));
  };

  const isAdmin = user?.role === 'counsellor';
  const isApproved = user?.status === 'approved';
  const isPending = user?.status === 'pending';
  const isRejectedOrDisabled = user?.status === 'rejected' || user?.status === 'disabled';

  return (
    <AuthContext.Provider
      value={{
        user,
        firebaseUser,
        isLoading,
        isAdmin,
        isApproved,
        isPending,
        isRejectedOrDisabled,
        signIn,
        register,
        signOut,
        reloadUser,
        updateDeclaredRounds,
        requestDeclaredRoundsChange,
        cancelDeclaredRoundsRequest,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
